#include <zephyr/kernel.h>
#include <zephyr/kernel_structs.h>
#include <wait_q.h>
#include <ksched.h>
#include <zephyr/spinlock.h>
#include <errno.h>
#include <zephyr/sys/util.h>
#include <zephyr/logging/log.h>

#ifndef CONFIG_NUM_METAIRQ_PRIORITIES
#define CONFIG_NUM_METAIRQ_PRIORITIES 0
#endif

static inline void flag_clear(uint32_t *flagp,
			      uint32_t bit)
{
	*flagp &= ~BIT(bit);
}

static inline void flag_set(uint32_t *flagp,
			    uint32_t bit)
{
	*flagp |= BIT(bit);
}

static inline bool flag_test(const uint32_t *flagp,
			     uint32_t bit)
{
	return (*flagp & BIT(bit)) != 0U;
}

static inline bool flag_test_and_clear(uint32_t *flagp,
				       int bit)
{
	bool ret = flag_test(flagp, bit);

	flag_clear(flagp, bit);

	return ret;
}

static inline void flags_set(uint32_t *flagp,
			     uint32_t flags)
{
	*flagp = flags;
}

static inline uint32_t flags_get(const uint32_t *flagp)
{
	return *flagp;
}

/* Lock to protect the internal state of all work items, work queues,
 * and pending_cancels.
 */
static struct k_spinlock lock;

/* Invoked by work thread */
static void handle_flush(struct k_work *work)
{
	ARG_UNUSED(work);
}

static inline void init_flusher(struct z_work_flusher *flusher)
{
	struct k_work *work = &flusher->work;

	k_sem_init(&flusher->sem, 0, 1);
	k_work_init(&flusher->work, handle_flush);
	flag_set(&work->flags, K_WORK_FLUSHING_BIT);
}

/* List of pending cancellations. */
static sys_slist_t pending_cancels;

/* Initialize a canceler record and add it to the list of pending
 * cancels.
 *
 * Invoked with work lock held.
 *
 * @param canceler the structure used to notify a waiting process.
 * @param work the work structure that is to be canceled
 */
static inline void init_work_cancel(struct z_work_canceller *canceler,
				    struct k_work *work)
{
	k_sem_init(&canceler->sem, 0, 1);
	canceler->work = work;
	sys_slist_append(&pending_cancels, &canceler->node);
}

/* Complete flushing of a work item.
 *
 * Invoked with work lock held.
 *
 * Invoked from a work queue thread.
 *
 * Reschedules.
 *
 * @param work the work architecture that has completed flushing.
 */
static void finalize_flush_locked(struct k_work *work)
{
	struct z_work_flusher *flusher
		= CONTAINER_OF(work, struct z_work_flusher, work);

	flag_clear(&work->flags, K_WORK_FLUSHING_BIT);

	k_sem_give(&flusher->sem);
}

/* Complete cancellation of a work item and unlock held lock.
 *
 * Invoked with work lock held.
 *
 * Invoked from a work queue thread.
 *
 * Reschedules.
 *
 * @param work the work structure that has completed cancellation
 */
static void finalize_cancel_locked(struct k_work *work)
{
	struct z_work_canceller *wc, *tmp;
	sys_snode_t *prev = NULL;

	/* Clear this first, so released high-priority threads don't
	 * see it when doing things.
	 */
	flag_clear(&work->flags, K_WORK_CANCELING_BIT);

	/* Search for and remove the matching container, and release
	 * what's waiting on the completion.  The same work item can
	 * appear multiple times in the list if multiple threads
	 * attempt to cancel it.
	 */
	SYS_SLIST_FOR_EACH_CONTAINER_SAFE(&pending_cancels, wc, tmp, node) {
		if (wc->work == work) {
			sys_slist_remove(&pending_cancels, prev, &wc->node);
			k_sem_give(&wc->sem);
		} else {
			prev = &wc->node;
		}
	}
}

void k_work_init(struct k_work *work,
		  k_work_handler_t handler)
{
	__ASSERT_NO_MSG(work != NULL);
	__ASSERT_NO_MSG(handler != NULL);

	*work = (struct k_work)Z_WORK_INITIALIZER(handler);

	SYS_PORT_TRACING_OBJ_INIT(k_work, work);
}

int k_work_busy_get(const struct k_work *work)
{
	k_spinlock_key_t key = k_spin_lock(&lock);
	int ret = flags_get(&work->flags) & K_WORK_MASK;

	k_spin_unlock(&lock, key);

	return ret;
}

/* Add a work item to the work queue.
 *
 * Invoked with work lock held.
 *
 * @param queue the queue on which the work item is to beSubmitted.
 * @param work the work item to be submitted.
 *
 * @retval 1 if the work item was not already queued and has been queued
 * @retval 2 if the work item was running and has been queued to the queue
 *           it was running on
 * @retval 0 if the work item was already queued and has not been
 *           requeued.
 * @retval -EBUSY if the work item is canceling, or the queue cannot
 *                accept new work items, or the work item is running on a
 *                different queue.
 * @retval -EINVAL if no queue is provided and the work item has never
 *                 been queued.
 */
static int submit_to_queue_locked(struct k_work *work,
				  struct k_work_q **queuep)
{
	if (work == NULL) {
		return -EINVAL;
	}

	int ret = 0;

	if (flag_test(&work->flags, K_WORK_CANCELING_BIT)) {
		/* Disallowed */
		ret = -EBUSY;
	} else if (!flag_test(&work->flags, K_WORK_QUEUED_BIT)) {
		/* Not currently queued */
		ret = 1;

		/* If no queue specified resubmit to last queue. */
		if (*queuep == NULL) {
			*queuep = work->queue;
		}

		/* If the work is currently running we have to use the
		 * queue it's running on to prevent handler
		 * re-entrancy.
		 */
		if (flag_test(&work->flags, K_WORK_RUNNING_BIT)) {
			__ASSERT_NO_MSG(work->queue != NULL);
			if (*queuep != work->queue) {
				ret = -EBUSY;
				goto out;
			}
			ret = 2;
		}

		bool chained = (_current == (*queuep != NULL ? &(*queuep)->thread : NULL))
			&& !k_is_in_isr();
		bool draining = (*queuep != NULL)
			&& flag_test(&(*queuep)->flags, K_WORK_QUEUE_DRAIN_BIT);
		bool plugged = (*queuep != NULL)
			&& flag_test(&(*queuep)->flags, K_WORK_QUEUE_PLUGGED_BIT);

		if (*queuep == NULL) {
			ret = -EINVAL;
		} else if (!flag_test(&(*queuep)->flags, K_WORK_QUEUE_STARTED_BIT)) {
			ret = -ENODEV;
		} else if (draining && !chained) {
			ret = -EBUSY;
		} else if (plugged && !draining) {
			ret = -EBUSY;
		} else {
			sys_slist_append(&(*queuep)->pending, &work->node);
			work->queue = *queuep;
			flag_set(&work->flags, K_WORK_QUEUED_BIT);

			(void)z_sched_wake(&(*queuep)->notifyq, 0, NULL);
		}
	} else {
		/* Already queued, do nothing. */
	}

out:
	return ret;
}

/* Flush a work item if necessary.
 *
 * Invoked with work lock held.
 *
 * Sleeps.
 *
 * @param work the work item that is to be flushed
 * @param flusher the tracker record used for the flush
 * @param key the spinlock key to use when waiting on the flusher.
 *
 * @retval true if the work was queued or running, and wait for
 *         completion was performed.
 * @retval false if the work was neither queued nor running.
 */
static bool work_flush_locked(struct k_work *work,
			      struct z_work_flusher *flusher,
			      k_spinlock_key_t key)
{
	bool need_flush = (flags_get(&work->flags)
			   & (K_WORK_QUEUED | K_WORK_RUNNING)) != 0U;

	if (need_flush) {
		struct k_work_q *queue = work->queue;

		__ASSERT_NO_MSG(queue != NULL);

		init_flusher(flusher);

		if (flag_test(&work->flags, K_WORK_QUEUED_BIT)) {
			sys_slist_insert(&queue->pending, &work->node,
					 &flusher->work.node);
		} else {
			sys_slist_prepend(&queue->pending,
					  &flusher->work.node);
		}
		/* Note: the flusher work is not marked queued, nor is
		 * its queue pointer set, because it is not a regular
		 * work item.  However, wake the queue thread in case
		 * it was already sleeping when we prepended.
		 */
		(void)z_sched_wake(&queue->notifyq, 0, NULL);

		k_spin_unlock(&lock, key);
		k_sem_take(&flusher->sem, K_FOREVER);
	} else {
		k_spin_unlock(&lock, key);
	}

	return need_flush;
}

/* Attempt to cancel a work item.
 *
 * Invoked with work lock held.
 *
 * @param work the work item to be canceled.
 *
 * @return the k_work_busy_get() status following the cancellation.
 */
static int cancel_async_locked(struct k_work *work)
{
	/* If we haven't already started canceling, do it now. */
	if (!flag_test(&work->flags, K_WORK_CANCELING_BIT)) {
		/* Remove it from the queue, if it's queued. */
		if (flag_test_and_clear(&work->flags, K_WORK_QUEUED_BIT)) {
			(void)sys_slist_find_and_remove(&work->queue->pending,
							&work->node);
		}

		/* If it's still running mark it as canceling. */
		if (flag_test(&work->flags, K_WORK_RUNNING_BIT)) {
			flag_set(&work->flags, K_WORK_CANCELING_BIT);
		}
	}

	return flags_get(&work->flags) & K_WORK_MASK;
}

/* Wait for a work item to complete being canceled.
 *
 * Invoked with work lock held.
 *
 * Sleeps.
 *
 * @param work the work item that is being canceled
 * @param canceler the tracker record used for the cancellation
 * @param key the spinlock key to use when waiting on the canceler.
 *
 * @retval true if the work was canceling and waited for completion
 * @retval false if the work was was not canceling
 */
static bool cancel_sync_locked(struct k_work *work,
			       struct z_work_canceller *canceler,
			       k_spinlock_key_t key)
{
	bool ret = flag_test(&work->flags, K_WORK_CANCELING_BIT);

	if (ret) {
		init_work_cancel(canceler, work);

		k_spin_unlock(&lock, key);
		k_sem_take(&canceler->sem, K_FOREVER);
	} else {
		k_spin_unlock(&lock, key);
	}

	return ret;
}

/* Loop executed by a work queue thread.
 *
 * @param work_q_ptr pointer to the work queue structure
 */
static void work_queue_main(void *work_q_ptr, void *p2, void *p3)
{
	ARG_UNUSED(p2);
	ARG_UNUSED(p3);

	struct k_work_q *queue = (struct k_work_q *)work_q_ptr;

	while (true) {
		sys_snode_t *node;
		struct k_work *work = NULL;
		k_work_handler_t handler = NULL;
		k_spinlock_key_t key = k_spin_lock(&lock);
		bool yield;

		/* Check for and prepare any new work. */
		node = sys_slist_get(&queue->pending);
		if (node != NULL) {
			/* Mark that there's some work active that's
			 * not on the pending list.
			 */
			flag_set(&queue->flags, K_WORK_QUEUE_BUSY_BIT);
			work = CONTAINER_OF(node, struct k_work, node);
			flag_set(&work->flags, K_WORK_RUNNING_BIT);
			flag_clear(&work->flags, K_WORK_QUEUED_BIT);

			/* Static code analysis tool can raise a false-positive violation
			 * in the line below that 'work' is checked for null after being
			 * dereferenced.
			 *
			 * The work is figured out by CONTAINER_OF, as a container
			 * of the node of type sys_snode_t. The only way the work can
			 * be NULL is if the node would be a NULL, which has just been
			 * checked above (if (node != NULL)). This means that the work
			 * will not be NULL if code reaches here.
			 */
			handler = work->handler;
		} else if (flag_test_and_clear(&queue->flags,
					       K_WORK_QUEUE_DRAIN_BIT)) {
			/* Not busy and draining: move threads waiting for
			 * drain to ready state.  The held spinlock inhibits
			 * immediate reschedule; released threads proceed
			 * when the queue thread invokes z_sched_wait() below.
			 *
			 * Note that we don't clear K_WORK_QUEUE_PLUGGABLE_BIT
			 * here so that the queue stays plugged if that was
			 * requested.
			 */
			(void)z_sched_wake_all(&queue->drainq, 1, NULL);
		} else if (flag_test(&queue->flags, K_WORK_QUEUE_STOP_BIT)) {
			/* User has requested that the queue stop. Clear the
			 * status flags and exit.
			 */
			flags_set(&queue->flags, K_WORK_QUEUE_NO_FLAGS);
			k_spin_unlock(&lock, key);
			return;
		} else {
			/* No work is available and no queue state requires
			 * special handling.
			 */
			;
		}

		if (work == NULL) {
			/* Nothing's had a chance to add work since we took
			 * the lock and found the queue empty.  Wait for
			 * something to happen.
			 */
			(void)z_sched_wait(&lock, key, &queue->notifyq,
					   K_FOREVER, NULL);
			continue;
		}

		k_spin_unlock(&lock, key);

		__ASSERT_NO_MSG(handler != NULL);
		handler(work);

		/* Mark the work item as no longer running, and deal
		 * with any cancellation and flushing issued while it
		 * was running.  Clear the BUSY flag and optionally
		 * yield to prevent starving other threads.
		 */
		key = k_spin_lock(&lock);

		flag_clear(&work->flags, K_WORK_RUNNING_BIT);
		if (flag_test(&work->flags, K_WORK_FLUSHING_BIT)) {
			finalize_flush_locked(work);
		}
		if (flag_test(&work->flags, K_WORK_CANCELING_BIT)) {
			finalize_cancel_locked(work);
		}

		flag_clear(&queue->flags, K_WORK_QUEUE_BUSY_BIT);
		yield = !flag_test(&queue->flags, K_WORK_QUEUE_NO_YIELD_BIT);
		k_spin_unlock(&lock, key);

		/* Optionally yield to prevent the work queue from
		 * starving other threads.
		 */
		if (yield) {
			k_yield();
		}
	}
}

void k_work_queue_init(struct k_work_q *queue)
{
	__ASSERT_NO_MSG(queue != NULL);

	*queue = (struct k_work_q) {
		.flags = 0,
	};

	SYS_PORT_TRACING_OBJ_INIT(k_work_queue, queue);
}

void k_work_queue_start(struct k_work_q *queue,
			k_thread_stack_t *stack,
			size_t stack_size,
			int prio,
			const struct k_work_queue_config *cfg)
{
	__ASSERT_NO_MSG(queue);
	__ASSERT_NO_MSG(stack);
	__ASSERT_NO_MSG(!flag_test(&queue->flags, K_WORK_QUEUE_STARTED_BIT));
	uint32_t flags = K_WORK_QUEUE_STARTED;

	SYS_PORT_TRACING_OBJ_FUNC_ENTER(k_work_queue, start, queue);

	sys_slist_init(&queue->pending);
	z_waitq_init(&queue->notifyq);
	z_waitq_init(&queue->drainq);

	if ((cfg != NULL) && cfg->no_yield) {
		flags |= K_WORK_QUEUE_NO_YIELD;
	}

	/* It hasn't actually been started yet, but all the state is in place
	 * so we can submit things and once the thread gets control it's ready
	 * to roll.
	 */
	flags_set(&queue->flags, flags);

	(void)k_thread_create(&queue->thread, stack, stack_size,
			      work_queue_main, queue, NULL, NULL,
			      prio, 0, K_FOREVER);

	if ((cfg != NULL) && (cfg->name != NULL)) {
		k_thread_name_set(&queue->thread, cfg->name);
	}

	if ((cfg != NULL) && (cfg->essential)) {
		queue->thread.base.user_options |= K_ESSENTIAL;
	}

	k_thread_start(&queue->thread);

	SYS_PORT_TRACING_OBJ_FUNC_EXIT(k_work_queue, start, queue);
}

int k_work_queue_drain(struct k_work_q *queue,
		       bool plug)
{
	__ASSERT_NO_MSG(queue);
	__ASSERT_NO_MSG(!k_is_in_isr());

	SYS_PORT_TRACING_OBJ_FUNC_ENTER(k_work_queue, drain, queue);

	int ret = 0;
	k_spinlock_key_t key = k_spin_lock(&lock);

	if (((flags_get(&queue->flags)
	      & (K_WORK_QUEUE_BUSY | K_WORK_QUEUE_DRAIN)) != 0U)
	    || plug
	    || !sys_slist_is_empty(&queue->pending)) {
		flag_set(&queue->flags, K_WORK_QUEUE_DRAIN_BIT);
		if (plug) {
			flag_set(&queue->flags, K_WORK_QUEUE_PLUGGED_BIT);
		}

		SYS_PORT_TRACING_OBJ_FUNC_BLOCKING(k_work_queue, drain, queue);
		(void)z_sched_wake(&queue->notifyq, 0, NULL);
		ret = z_sched_wait(&lock, key, &queue->drainq,
				   K_FOREVER, NULL);
	} else {
		k_spin_unlock(&lock, key);
	}

	SYS_PORT_TRACING_OBJ_FUNC_EXIT(k_work_queue, drain, queue, ret);

	return ret;
}

int k_work_queue_unplug(struct k_work_q *queue)
{
	__ASSERT_NO_MSG(queue);

	SYS_PORT_TRACING_OBJ_FUNC_ENTER(k_work_queue, unplug, queue);

	int ret = -EALREADY;
	k_spinlock_key_t key = k_spin_lock(&lock);

	if (flag_test_and_clear(&queue->flags, K_WORK_QUEUE_PLUGGED_BIT)) {
		ret = 0;
	}

	k_spin_unlock(&lock, key);

	SYS_PORT_TRACING_OBJ_FUNC_EXIT(k_work_queue, unplug, queue, ret);

	return ret;
}

int k_work_submit_to_queue(struct k_work_q *queue,
			   struct k_work *work)
{
	SYS_PORT_TRACING_OBJ_FUNC_ENTER(k_work, submit_to_queue, queue, work);

	k_spinlock_key_t key = k_spin_lock(&lock);
	int ret = submit_to_queue_locked(work, &queue);

	/* submit_to_queue_locked() wakes the work queue thread if
	 * required, which may result in a reschedule point when the
	 * spinlock is released.
	 */
	k_spin_unlock(&lock, key);

	SYS_PORT_TRACING_OBJ_FUNC_EXIT(k_work, submit_to_queue, queue, work, ret);

	return ret;
}

int k_work_submit(struct k_work *work)
{
	SYS_PORT_TRACING_OBJ_FUNC_ENTER(k_work, submit, work);

	int ret = k_work_submit_to_queue(&k_sys_work_q, work);

	SYS_PORT_TRACING_OBJ_FUNC_EXIT(k_work, submit, work, ret);

	return ret;
}

bool k_work_flush(struct k_work *work,
		  struct k_work_sync *sync)
{
	__ASSERT_NO_MSG(work != NULL);
	__ASSERT_NO_MSG(!flag_test(&work->flags, K_WORK_DELAYABLE_BIT));
	__ASSERT_NO_MSG(!k_is_in_isr());
	__ASSERT_NO_MSG(sync != NULL);
#ifdef CONFIG_KERNEL_COHERENCE
	__ASSERT_NO_MSG(sys_cache_is_mem_coherent(sync));
#endif /* CONFIG_KERNEL_COHERENCE */

	SYS_PORT_TRACING_OBJ_FUNC_ENTER(k_work, flush, work);

	struct z_work_flusher *flusher = &sync->flusher;
	k_spinlock_key_t key = k_spin_lock(&lock);

	/* work_flush_locked() releases lock */
	bool ret = work_flush_locked(work, flusher, key);

	SYS_PORT_TRACING_OBJ_FUNC_EXIT(k_work, flush, work, ret);

	return ret;
}

int k_work_cancel(struct k_work *work)
{
	__ASSERT_NO_MSG(work != NULL);
	__ASSERT_NO_MSG(!flag_test(&work->flags, K_WORK_DELAYABLE_BIT));

	SYS_PORT_TRACING_OBJ_FUNC_ENTER(k_work, cancel, work);

	k_spinlock_key_t key = k_spin_lock(&lock);
	int ret = cancel_async_locked(work);

	k_spin_unlock(&lock, key);

	SYS_PORT_TRACING_OBJ_FUNC_EXIT(k_work, cancel, work, ret);

	return ret;
}

bool k_work_cancel_sync(struct k_work *work,
			struct k_work_sync *sync)
{
	__ASSERT_NO_MSG(work != NULL);
	__ASSERT_NO_MSG(!flag_test(&work->flags, K_WORK_DELAYABLE_BIT));
	__ASSERT_NO_MSG(sync != NULL);
	__ASSERT_NO_MSG(!k_is_in_isr());
#ifdef CONFIG_KERNEL_COHERENCE
	__ASSERT_NO_MSG(sys_cache_is_mem_coherent(sync));
#endif /* CONFIG_KERNEL_COHERENCE */

	SYS_PORT_TRACING_OBJ_FUNC_ENTER(k_work, cancel_sync, work, sync);

	struct z_work_canceller *canceler = &sync->canceler;
	k_spinlock_key_t key = k_spin_lock(&lock);
	bool pending = (flags_get(&work->flags) & K_WORK_MASK) != 0U;
	bool ret = false;

	if (pending) {
		(void)cancel_async_locked(work);
		/* cancel_sync_locked() releases lock */
		(void)cancel_sync_locked(work, canceler, key);
		ret = true;
	} else {
		k_spin_unlock(&lock, key);
	}

	SYS_PORT_TRACING_OBJ_FUNC_EXIT(k_work, cancel_sync, work, sync, ret);

	return ret;
}

/* Timeout handler for delayable work.
 *
 * Invoked by timeout infrastructure with timeout lock held.
 *
 * @param to pointer to the timeout structure, which is also the
 * k_work_delayable structure.
 */
static void work_timeout(struct _timeout *to)
{
	struct k_work_delayable *dwork
		= CONTAINER_OF(to, struct k_work_delayable, timeout);
	struct k_work *wp = &dwork->work;
	k_spinlock_key_t key = k_spin_lock(&lock);
	struct k_work_q *queue = NULL;

	/* If the work is still marked delayed (wasn't canceled before
	 * the timeout expired), then submit it to the queue.
	 */
	if (flag_test_and_clear(&wp->flags, K_WORK_DELAYED_BIT)) {
		queue = dwork->queue;
		(void)submit_to_queue_locked(wp, &queue);
	}

	k_spin_unlock(&lock, key);
}

void k_work_init_delayable(struct k_work_delayable *dwork,
			   k_work_handler_t handler)
{
	__ASSERT_NO_MSG(dwork != NULL);
	__ASSERT_NO_MSG(handler != NULL);

	*dwork = (struct k_work_delayable){
		.work = {
			.handler = handler,
			.flags = K_WORK_DELAYABLE,
		},
	};
	z_init_timeout(&dwork->timeout);

	SYS_PORT_TRACING_OBJ_INIT(k_work_delayable, dwork);
}

static inline int work_delayable_busy_get_locked(const struct k_work_delayable *dwork)
{
	return flags_get(&dwork->work.flags) & K_WORK_MASK;
}

int k_work_delayable_busy_get(const struct k_work_delayable *dwork)
{
	k_spinlock_key_t key = k_spin_lock(&lock);
	int ret = work_delayable_busy_get_locked(dwork);

	k_spin_unlock(&lock, key);
	return ret;
}

/* Attempt to schedule a work item for future submission.
 *
 * Invoked with work lock held.
 *
 * See k_work_schedule_for_queue() forFlush/Semantics.
 *
 * @param queuep pointer to a pointer to a queue.  On input this
 * should dereference to the proposed queue (which may be null); after
 * completion it will be null if the work was not submitted or will
 * reference the queue to which the work was submitted.
 * @param dwork the delayed work structure
 * @param delay the delay before the work should be submitted.
 */
static int schedule_for_queue_locked(struct k_work_q **queuep,
				     struct k_work_delayable *dwork,
				     k_timeout_t delay)
{
	int ret = 1;
	struct k_work *work = &dwork->work;

	if (K_TIMEOUT_EQ(delay, K_NO_WAIT)) {
		return submit_to_queue_locked(work, queuep);
	}

	if (flag_test(&work->flags, K_WORK_CANCELING_BIT)) {
		/* Disallowed */
		ret = -EBUSY;
	} else if ((flags_get(&work->flags) & (K_WORK_DELAYED | K_WORK_QUEUED))
		   == 0U) {
		/* Not scheduled or queued.  If no queue specified
		 * use the previous queue.
		 */
		if (*queuep == NULL) {
			*queuep = work->queue;
		}

		bool chained = (_current == (*queuep != NULL ? &(*queuep)->thread : NULL))
			&& !k_is_in_isr();
		bool draining = (*queuep != NULL)
			&& flag_test(&(*queuep)->flags, K_WORK_QUEUE_DRAIN_BIT);
		bool plugged = (*queuep != NULL)
			&& flag_test(&(*queuep)->flags, K_WORK_QUEUE_PLUGGED_BIT);

		/* Make sure the queue is valid. */
		if (*queuep == NULL) {
			ret = -EINVAL;
		} else if (!flag_test(&(*queuep)->flags, K_WORK_QUEUE_STARTED_BIT)) {
			ret = -ENODEV;
		} else if (draining && !chained) {
			ret = -EBUSY;
		} else if (plugged && !draining) {
			ret = -EBUSY;
		} else {
			dwork->queue = *queuep;
			flag_set(&work->flags, K_WORK_DELAYED_BIT);
			z_add_timeout(&dwork->timeout, work_timeout, delay);
		}
	} else {
		/* Already scheduled or queued, do nothing. */
		ret = 0;
	}

	return ret;
}

/* Unschedule a work item if it has been scheduled.
 *
 * Invoked with work lock held.
 *
 * @param dwork the delayed work structure
 *
 * @retval true if work was delayed and so the timeout was aborted.
 * @retval false if work was not delayed so no timeout action was
 * taken.
 */
static inline bool unschedule_locked(struct k_work_delayable *dwork)
{
	bool ret = false;
	struct k_work *work = &dwork->work;

	/* If scheduled, try to cancel.  If it fails, that means the
	 * callback has been dequeued and will inevitably run (or has
	 * already run), so treat that as "undelayed" and return
	 * false.
	 */
	if (flag_test_and_clear(&work->flags, K_WORK_DELAYED_BIT)) {
		ret = z_abort_timeout(&dwork->timeout) == 0;
	}

	return ret;
}

/* Full cancellation of a delayable work item.
 *
 * Invoked with work lock held.
 *
 * Unschedules the delayed part then cancels the standard work item.
 *
 * @param dwork the delayed work structure.
 *
 * @return the k_work_busy_get() flags.
 */
static int cancel_delayable_async_locked(struct k_work_delayable *dwork)
{
	(void)unschedule_locked(dwork);

	return cancel_async_locked(&dwork->work);
}

int k_work_schedule_for_queue(struct k_work_q *queue,
			       struct k_work_delayable *dwork,
			       k_timeout_t delay)
{
	__ASSERT_NO_MSG(dwork != NULL);

	SYS_PORT_TRACING_OBJ_FUNC_ENTER(k_work, schedule_for_queue, queue, dwork, delay);

	k_spinlock_key_t key = k_spin_lock(&lock);
	int ret = schedule_for_queue_locked(&queue, dwork, delay);

	k_spin_unlock(&lock, key);

	SYS_PORT_TRACING_OBJ_FUNC_EXIT(k_work, schedule_for_queue, queue, dwork, delay, ret);

	return ret;
}

int k_work_schedule(struct k_work_delayable *dwork,
			   k_timeout_t delay)
{
	SYS_PORT_TRACING_OBJ_FUNC_ENTER(k_work, schedule, dwork, delay);

	int ret = k_work_schedule_for_queue(&k_sys_work_q, dwork, delay);

	SYS_PORT_TRACING_OBJ_FUNC_EXIT(k_work, schedule, dwork, delay, ret);

	return ret;
}

int k_work_reschedule_for_queue(struct k_work_q *queue,
				 struct k_work_delayable *dwork,
				 k_timeout_t delay)
{
	__ASSERT_NO_MSG(dwork != NULL);

	SYS_PORT_TRACING_OBJ_FUNC_ENTER(k_work, reschedule_for_queue, queue, dwork, delay);

	int ret;
	k_spinlock_key_t key = k_spin_lock(&lock);

	/* Remove any active scheduling. */
	(void)unschedule_locked(dwork);

	/* If the work is queued and the delay is non-zero we need to
	 * pull it off the queue so we can schedule it.
	 */
	if (!K_TIMEOUT_EQ(delay, K_NO_WAIT)
	    && flag_test_and_clear(&dwork->work.flags, K_WORK_QUEUED_BIT)) {
		(void)sys_slist_find_and_remove(&dwork->work.queue->pending,
						&dwork->work.node);
	}

	/* Schedule the item under the standard conditions. */
	ret = schedule_for_queue_locked(&queue, dwork, delay);
	if (ret == 1) {
		/* Distinguish fresh schedule from reschedule that
		 * cleared a previous queued item.
		 */
		;
	}

	k_spin_unlock(&lock, key);

	SYS_PORT_TRACING_OBJ_FUNC_EXIT(k_work, reschedule_for_queue, queue, dwork, delay, ret);

	return ret;
}

int k_work_reschedule(struct k_work_delayable *dwork,
			     k_timeout_t delay)
{
	SYS_PORT_TRACING_OBJ_FUNC_ENTER(k_work, reschedule, dwork, delay);

	int ret = k_work_reschedule_for_queue(&k_sys_work_q, dwork, delay);

	SYS_PORT_TRACING_OBJ_FUNC_EXIT(k_work, reschedule, dwork, delay, ret);

	return ret;
}

int k_work_cancel_delayable(struct k_work_delayable *dwork)
{
	__ASSERT_NO_MSG(dwork != NULL);

	SYS_PORT_TRACING_OBJ_FUNC_ENTER(k_work, cancel_delayable, dwork);

	k_spinlock_key_t key = k_spin_lock(&lock);
	int ret = cancel_delayable_async_locked(dwork);

	k_spin_unlock(&lock, key);

	SYS_PORT_TRACING_OBJ_FUNC_EXIT(k_work, cancel_delayable, dwork, ret);

	return ret;
}

bool k_work_cancel_delayable_sync(struct k_work_delayable *dwork,
				  struct k_work_sync *sync)
{
	__ASSERT_NO_MSG(dwork != NULL);
	__ASSERT_NO_MSG(sync != NULL);
	__ASSERT_NO_MSG(!k_is_in_isr());
#ifdef CONFIG_KERNEL_COHERENCE
	__ASSERT_NO_MSG(sys_cache_is_mem_coherent(sync));
#endif /* CONFIG_KERNEL_COHERENCE */

	SYS_PORT_TRACING_OBJ_FUNC_ENTER(k_work, cancel_delayable_sync, dwork, sync);

	struct z_work_canceller *canceler = &sync->canceler;
	k_spinlock_key_t key = k_spin_lock(&lock);
	bool pending = (work_delayable_busy_get_locked(dwork) != 0);
	bool ret = false;

	if (pending) {
		(void)cancel_delayable_async_locked(dwork);
		(void)cancel_sync_locked(&dwork->work, canceler, key);
		ret = true;
	} else {
		k_spin_unlock(&lock, key);
	}

	SYS_PORT_TRACING_OBJ_FUNC_EXIT(k_work, cancel_delayable_sync, dwork, sync, ret);

	return ret;
}

bool k_work_flush_delayable(struct k_work_delayable *dwork,
			    struct k_work_sync *sync)
{
	__ASSERT_NO_MSG(dwork != NULL);
	__ASSERT_NO_MSG(sync != NULL);
	__ASSERT_NO_MSG(!k_is_in_isr());
#ifdef CONFIG_KERNEL_COHERENCE
	__ASSERT_NO_MSG(sys_cache_is_mem_coherent(sync));
#endif /* CONFIG_KERNEL_COHERENCE */

	SYS_PORT_TRACING_OBJ_FUNC_ENTER(k_work, flush_delayable, dwork, sync);

	struct k_work *work = &dwork->work;
	struct z_work_flusher *flusher = &sync->flusher;
	k_spinlock_key_t key = k_spin_lock(&lock);

	/* If it's delayed release the timeout and submit it
	 * immediately.
	 */
	if (unschedule_locked(dwork)) {
		struct k_work_q *queue = dwork->queue;

		(void)submit_to_queue_locked(work, &queue);
	}

	/* Wait for it to finish.  Releases lock. */
	bool ret = work_flush_locked(work, flusher, key);

	SYS_PORT_TRACING_OBJ_FUNC_EXIT(k_work, flush_delayable, dwork, sync, ret);

	return ret;
}

int k_work_queue_stop(struct k_work_q *queue, k_timeout_t timeout)
{
	__ASSERT_NO_MSG(queue);

	SYS_PORT_TRACING_OBJ_FUNC_ENTER(k_work_queue, stop, queue, timeout);

	k_spinlock_key_t key = k_spin_lock(&lock);

	if (!flag_test(&queue->flags, K_WORK_QUEUE_STARTED_BIT)) {
		k_spin_unlock(&lock, key);
		SYS_PORT_TRACING_OBJ_FUNC_EXIT(k_work_queue, stop, queue, timeout, -EALREADY);
		return -EALREADY;
	}

	if (!flag_test(&queue->flags, K_WORK_QUEUE_PLUGGED_BIT)) {
		k_spin_unlock(&lock, key);
		SYS_PORT_TRACING_OBJ_FUNC_EXIT(k_work_queue, stop, queue, timeout, -EBUSY);
		return -EBUSY;
	}

	if (!sys_slist_is_empty(&queue->pending)) {
		k_spin_unlock(&lock, key);
		SYS_PORT_TRACING_OBJ_FUNC_EXIT(k_work_queue, stop, queue, timeout, -EBUSY);
		return -EBUSY;
	}

	flag_set(&queue->flags, K_WORK_QUEUE_STOP_BIT);
	SYS_PORT_TRACING_OBJ_FUNC_BLOCKING(k_work_queue, stop, queue, timeout);
	(void)z_sched_wake(&queue->notifyq, 0, NULL);
	k_spin_unlock(&lock, key);
	int ret = k_thread_join(&queue->thread, timeout);
	if (ret != 0) {
		key = k_spin_lock(&lock);
		flag_clear(&queue->flags, K_WORK_QUEUE_STOP_BIT);
		k_spin_unlock(&lock, key);
	}

	SYS_PORT_TRACING_OBJ_FUNC_EXIT(k_work_queue, stop, queue, timeout, ret);
	return ret;
}
